module cube_checker(\n  input signed [23:0] in0_0, in0_1, in0_2,\n  input signed [23:0] in1_0, in1_1, in1_2,\n  input signed [23:0] in2_0, in2_1, in2_2,\n  input signed [23:0] in3_0, in3_1, in3_2,\n  input signed [23:0] in4_0, in4_1, in4_2,\n  input signed [23:0] in5_0, in5_1, in5_2,\n  input signed [23:0] in6_0, in6_1, in6_2,\n  input signed [23:0] in7_0, in7_1, in7_2,\n  output reg is_cube,\n  output reg [23:0] out0_0, out0_1, out0_2,\n  output reg [23:0] out1_0, out1_1, out1_2,\n  output reg [23:0] out2_0, out2_1, out2_2,\n  output reg [23:0] out3_0, out3_1, out3_2,\n  output reg [23:0] out4_0, out4_1, out4_2,\n  output reg [23:0] out5_0, out5_1, out5_2,\n  output reg [23:0] out6_0, out6_1, out6_2,\n  output reg [23:0] out7_0, out7_1, out7_2\n);\n  \n  reg signed [23:0] points [0:7][0:2];\n  reg signed [63:0] dist2 [0:27];\n  reg signed [63:0] min_dist2;\n  reg found_min;\n  reg [2:0] edge_count [0:7];\n  reg [2:0] face_count [0:7];\n  reg [2:0] space_count [0:7];\n  reg [7:0] edge_errors, face_errors, space_errors;\n  reg valid_distances;\n  integer i, j, k, p_idx;\n  \n  always @(*) begin\n    // Assign input points to array\n    points[0][0] = in0_0;\n    points[0][1] = in0_1;\n    points[0][2] = in0_2;\n    points[1][0] = in1_0;\n    points[1][1] = in1_1;\n    points[1][2] = in1_2;\n    points[2][0] = in2_0;\n    points[2][1] = in2_1;\n    points[2][2] = in2_2;\n    points[3][0] = in3_0;\n    points[3][1] = in3_1;\n    points[3][2] = in3_2;\n    points[4][0] = in4_0;\n    points[4][1] = in4_1;\n    points[4][2] = in4_2;\n    points[5][0] = in5_0;\n    points[5][1] = in5_1;\n    points[5][2] = in5_2;\n    points[6][0] = in6_0;\n    points[6][1] = in6_1;\n    points[6][2] = in6_2;\n    points[7][0] = in7_0;\n    points[7][1] = in7_1;\n    points[7][2] = in7_2;\n    \n    // Compute squared distances\n    p_idx = 0;\n    for (i = 0; i < 8; i = i + 1) begin\n      for (j = i + 1; j < 8; j = j + 1) begin\n        dist2[p_idx] =\n          (points[i][0] - points[j][0]) * (points[i][0] - points[j][0]) +\n          (points[i][1] - points[j][1]) * (points[i][1] - points[j][1]) +\n          (points[i][2] - points[j][2]) * (points[i][2] - points[j][2]);\n        p_idx = p_idx + 1;\n      end\n    end\n    \n    // Find minimal non-zero distance\n    min_dist2 = 64'h7FFFFFFFFFFFFFFF;\n    found_min = 1'b0;\n    for (k = 0; k < 28; k = k + 1) begin\n      if (dist2[k] != 0 && dist2[k] < min_dist2) begin\n        min_dist2 = dist2[k];\n        found_min = 1'b1;\n      end\n    end\n    \n    // Initialize counters\n    for (i = 0; i < 8; i = i + 1) begin\n      edge_count[i] = 3'd0;\n      face_count[i] = 3'd0;\n      space_count[i] = 3'd0;\n    end\n    edge_errors = 8'd0;\n    face_errors = 8'd0;\n    space_errors = 8'd0;\n    valid_distances = 1'b1;\n    \n    // Count distance categories\n    p_idx = 0;\n    for (i = 0; i < 8; i = i + 1) begin\n      for (j = i + 1; j < 8; j = j + 1) begin\n        if (dist2[p_idx] == 64'd0) begin\n          valid_distances = 1'b0;\n        end else if (dist2[p_idx] == min_dist2) begin\n          edge_count[i] = edge_count[i] + 3'd1;\n          edge_count[j] = edge_count[j] + 3'd1;\n        end else if (dist2[p_idx] == (min_dist2 << 1)) begin\n          face_count[i] = face_count[i] + 3'd1;\n          face_count[j] = face_count[j] + 3'd1;\n        end else if (dist2[p_idx] == (min_dist2 * 3)) begin\n          space_count[i] = space_count[i] + 3'd1;\n          space_count[j] = space_count[j] + 3'd1;\n        end else begin\n          valid_distances = 1'b0;\n        end\n        p_idx = p_idx + 1;\n      end\n    end\n    \n    // Check per-vertex counts\n    for (i = 0; i < 8; i = i + 1) begin\n      if (edge_count[i] != 3'd3) edge_errors = edge_errors + 8'd1;\n      if (face_count[i] != 3'd3) face_errors = face_errors + 8'd1;\n      if (space_count[i] != 3'd1) space_errors = space_errors + 8'd1;\n    end\n    \n    // Set outputs\n    out0_0 = points[0][0];\n    out0_1 = points[0][1];\n    out0_2 = points[0][2];\n    out1_0 = points[1][0];\n    out1_1 = points[1][1];\n    out1_2 = points[1][2];\n    out2_0 = points[2][0];\n    out2_1 = points[2][1];\n    out2_2 = points[2][2];\n    out3_0 = points[3][0];\n    out3_1 = points[3][1];\n    out3_2 = points[3][2];\n    out4_0 = points[4][0];\n    out4_1 = points[4][1];\n    out4_2 = points[4][2];\n    out5_0 = points[5][0];\n    out5_1 = points[5][1];\n    out5_2 = points[5][2];\n    out6_0 = points[6][0];\n    out6_1 = points[6][1];\n    out6_2 = points[6][2];\n    out7_0 = points[7][0];\n    out7_1 = points[7][1];\n    out7_2 = points[7][2];\n    \n    is_cube = valid_distances && found_min &&\n              (edge_errors == 0) &&\n              (face_errors == 0) &&\n              (space_errors == 0);\n  end\nendmodule